package counter

import "unicode"

// TextCounter is a correct implementation of the Counter contract: it counts
// the number of lines, letters, and total characters in the strings added to
// it via AddString.
//
// Semantics:
//   - Characters counts every rune in the added strings.
//   - Letters counts every Unicode letter (unicode.IsLetter), so it is not
//     limited to ASCII.
//   - Lines counts the number of lines. A trailing newline does not start a
//     new empty line, so a string of N newlines with no trailing content is N
//     lines, while a final line without a terminating newline adds one more.
type TextCounter struct {
	newlines   int
	characters int
	letters    int
	lastChar   rune
}

// Compile-time check that TextCounter satisfies the Counter contract.
var _ Counter = (*TextCounter)(nil)

// AddString records the line, letter, and character counts for s. It may be
// called any number of times; the counts accumulate across calls.
func (c *TextCounter) AddString(s string) {
	for _, char := range s {
		c.lastChar = char
		if char == '\n' {
			c.newlines++
		} else if unicode.IsLetter(char) {
			c.letters++
		}
		c.characters++
	}
}

// Lines reports the total number of lines in the added strings.
func (c TextCounter) Lines() int {
	switch {
	case c.characters == 0:
		return 0
	case c.lastChar == '\n':
		return c.newlines
	default:
		return c.newlines + 1
	}
}

// Letters reports the total number of letters in the added strings.
func (c TextCounter) Letters() int { return c.letters }

// Characters reports the total number of characters (runes) in the added strings.
func (c TextCounter) Characters() int { return c.characters }

