package counter

import "testing"

func TestTextCounterSanity(t *testing.T) {
	cases := []struct {
		inputs       []string
		lines, letters, chars int
	}{
		{nil, 0, 0, 0},                                  // empty
		{[]string{"abc"}, 1, 3, 3},                     // one line, no newline
		{[]string{"abc\n"}, 1, 3, 4},                   // trailing newline
		{[]string{"abc\ndef"}, 2, 6, 7},                // two lines, no trailing newline
		{[]string{"abc\ndef\n"}, 2, 6, 8},             // trailing newline
		{[]string{"a\n", "b\n", "c"}, 3, 3, 5},        // accumulated across AddString calls
		{[]string{"héllo"}, 1, 5, 5},                  // unicode letters (é is a letter)
		{[]string{"héllo wörld"}, 1, 10, 11},          // unicode letters + space
		{[]string{"123 456"}, 1, 0, 7},                // digits are not letters
		{[]string{"\n\n\n"}, 3, 0, 3},                 // only newlines
	}
	for _, tc := range cases {
		var c Counter = &TextCounter{}
		for _, s := range tc.inputs {
			c.AddString(s)
		}
		if got := c.Lines(); got != tc.lines {
			t.Errorf("Lines() = %d, want %d (inputs %q)", got, tc.lines, tc.inputs)
		}
		if got := c.Letters(); got != tc.letters {
			t.Errorf("Letters() = %d, want %d (inputs %q)", got, tc.letters, tc.inputs)
		}
		if got := c.Characters(); got != tc.chars {
			t.Errorf("Characters() = %d, want %d (inputs %q)", got, tc.chars, tc.inputs)
		}
	}
}

